+<?php
+
+namespace App\Models;
+
+use Illuminate\Database\Eloquent\Model;
+
+class UploadLink extends Model
+{
+    protected $fillable = [
+        'title',
+        'image',
+        'link',
+    ];
+
+    /**
+     * Accessor: embed link otomatis.
+     */
+    public function getEmbedLinkAttribute()
+    {
+        $url = $this->link;
+
+        if (!$url) {
+            return null;
+        }
+
+        // --- YouTube ---
+        if (str_contains($url, 'watch?v=')) {
+            return str_replace('watch?v=', 'embed/', $url);
+        }
+
+        if (str_contains($url, 'youtu.be/')) {
+            return str_replace('youtu.be/', 'www.youtube.com/embed/', $url);
+        }
+
+        // --- Instagram ---
+        if (str_contains($url, 'instagram.com')) {
+            // pastikan ada trailing slash
+            $url = rtrim($url, '/') . '/';
+            // tambahkan embed
+            if (!str_contains($url, '/embed')) {
+                $url .= 'embed';
+            }
+            return $url;
+        }
+
+        // fallback: kembalikan apa adanya
+        return $url;
+    }
+
+    /**
+     * Accessor: tentukan tipe konten (youtube, instagram, image).
+     */
+    public function getTypeAttribute()
+    {
+        if ($this->image) {
+            return 'image';
+        }
+
+        if ($this->link) {
+            if (str_contains($this->link, 'youtube.com') || str_contains($this->link, 'youtu.be')) {
+                return 'youtube';
+            }
+
+            if (str_contains($this->link, 'instagram.com')) {
+                return 'instagram';
+            }
+        }
+
+        return 'unknown';
+    }
+}

